import { Gallery } from '../types';

const STORAGE_KEY = 'tag_galleries';

const delay = (ms: number) => new Promise((res) => setTimeout(res, ms));

const DEFAULT_GALLERIES: Gallery[] = [
    {
        id: 'gallery_weekly_showcase',
        name: 'WEEKLY SHOWCASE',
        page: 'moes',
        description: 'Live stream highlights and DJ sets.',
        images: [],
        createdAt: new Date().toISOString()
    },
    {
        id: 'gallery_under_la',
        name: 'UNDER LA',
        page: 'moes',
        description: 'Monday night community events and performances',
        images: [],
        createdAt: new Date().toISOString()
    },
    {
        id: 'gallery_studio_sessions',
        name: 'STUDIO SESSIONS',
        page: 'moes',
        description: 'Raw, unfiltered moments from recording and production blocks.',
        images: [],
        createdAt: new Date().toISOString()
    }
];

export const getGalleries = async (): Promise<Gallery[]> => {
    await delay(300); // Simulate network latency
    try {
        const data = localStorage.getItem(STORAGE_KEY);
        // If storage is empty or contains an empty array, seed with defaults
        if (!data || data === '[]') {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_GALLERIES));
            return DEFAULT_GALLERIES;
        }
        return JSON.parse(data);
    } catch (e) {
        console.error("Failed to load galleries", e);
        return [];
    }
};

export const addGallery = async (gallery: Gallery): Promise<Gallery> => {
    await delay(300); // Simulate network latency
    try {
        const galleries = await getGalleries();
        const newGallery = { ...gallery, id: `gallery_${gallery.name.toLowerCase().replace(/ /g, '_')}`, createdAt: new Date().toISOString() };
        localStorage.setItem(STORAGE_KEY, JSON.stringify([...galleries, newGallery]));
        return newGallery;
    } catch (e) {
        console.error("Failed to add gallery", e);
        return {} as Gallery;
    }
};

export const removeGallery = async (galleryId: string): Promise<void> => {
    await delay(300); // Simulate network latency
    try {
        const galleries = await getGalleries();
        const updatedGalleries = galleries.filter((gallery) => gallery.id !== galleryId);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedGalleries));
    } catch (e) {
        console.error("Failed to remove gallery", e);
    }
};

export const updateGallery = async (gallery: Gallery): Promise<void> => {
    await delay(300); // Simulate network latency
    try {
        const galleries = await getGalleries();
        const updatedGalleries = galleries.map((g) => (g.id === gallery.id ? gallery : g));
        localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedGalleries));
    } catch (e) {
        console.error("Failed to update gallery", e);
    }
};

export const uploadImage = async (galleryId: string, image: File): Promise<string | null> => {
    await delay(1000); // Simulate network latency for upload

    try {
        const galleries = await getGalleries();
