export const GalleryManager: React.FC<GalleryManagerProps> = ({ addToast }) => {
    const [galleries, setGalleries] = useState<Gallery[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [selectedGallery, setSelectedGallery] = useState<Gallery | null>(null);

    useEffect(() => {
        loadGalleries();
    }, []);

    const loadGalleries = async () => {
        setIsLoading(true);
        const data = await getGalleries();
        setGalleries(data);
        setIsLoading(false);
    };

    const handleCreateGallery = async (name: string, page: Gallery['page'], description: string) => {
        try {
            const newGallery = await createGallery(name, page, description);
            setGalleries(prev => [...prev, newGallery]);
            addToast(`Gallery "${name}" created successfully.`);
        } catch (e) {
            addToast('Failed to create gallery.');
        }
    };

    const handleDeleteGallery = async (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        if (window.confirm('Are you sure you want to delete this gallery? This action cannot be undone.')) {
            try {
                await deleteGallery(id);
                setGalleries(prev => prev.filter(g => g.id !== id));
                addToast('Gallery deleted.');
            } catch (e) {
                addToast('Failed to delete gallery.');
            }
        }
    };

    const handleUploadImage = async (file: File) => {
        if (!selectedGallery) return;
        try {
            const newImage = await uploadImageToGallery(selectedGallery.id, file);
            // Update local state to reflect change immediately
            const updatedGallery = { ...selectedGallery, images: [...selectedGallery.images, newImage] };
            setSelectedGallery(updatedGallery);
            setGalleries(prev => prev.map(g => g.id === updatedGallery.id ? updatedGallery : g));
            addToast('Image uploaded successfully.');
        } catch (e) {
            addToast('Failed to upload image.');
        }
    };

    const handleDeleteImage = async (imageId: string) => {
        if (!selectedGallery) return;
        if (!window.confirm('Delete this image?')) return;

        try {
            await deleteImageFromGallery(selectedGallery.id, imageId);
            const updatedGallery = { ...selectedGallery, images: selectedGallery.images.filter(img => img.id !== imageId) };
            setSelectedGallery(updatedGallery);
            setGalleries(prev => prev.map(g => g.id === updatedGallery.id ? updatedGallery : g));
            addToast('Image deleted.');
        } catch (e) {
            addToast('Failed to delete image.');
        }
    };

    const handleReorderImages = async (newImages: GalleryImage[]) => {
        if (!selectedGallery) return;

        // Optimistic UI Update
        const updatedGallery = { ...selectedGallery, images: newImages };
        setSelectedGallery(updatedGallery);
        setGalleries(prev => prev.map(g => g.id === updatedGallery.id ? updatedGallery : g));

        try {
            await updateGalleryImages(selectedGallery.id, newImages);
            addToast('Image order saved.');
        } catch (e) {
            addToast('Failed to save image order.');
            // Revert on error (could be implemented more robustly with previous state backup)
            loadGalleries();
        }
    };

    if (isLoading) return <div className="flex justify-center p-12"><LoadingSpinnerIcon /></div>;

    return (
        <section>
             <div className="flex justify-between items-center mb-8">
                <div>
                    <h2 className="text-3xl font-bold uppercase tracking-widest text-white">Gallery Management</h2>
                    <p className="text-gray-400 mt-1">Organize and manage image collections per page.</p>
                </div>
                <button 
                    onClick={() => setIsCreateModalOpen(true)}
                    className="px-6 py-2 bg-gradient-to-r from-cyan-500 to-blue-500 text-black font-bold rounded-full hover:scale-105 transition-transform flex items-center gap-2"
                >
                    <span>+ Create Gallery</span>
                </button>
            </div>

            {galleries.length === 0 ? (
                <div className="text-center py-12 bg-gray-800/30 rounded-lg border border-gray-700 border-dashed">
                    <p className="text-gray-400 mb-4">No galleries found.</p>
                    <button onClick={() => setIsCreateModalOpen(true)} className="text-cyan-400 hover:underline">Create your first gallery</button>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {galleries.map(gallery => (
                        <GalleryCard 
                            key={gallery.id} 
                            gallery={gallery} 
                            onClick={() => setSelectedGallery(gallery)}
                            onDelete={(e) => handleDeleteGallery(e, gallery.id)}
                        />
                    ))}
                </div>
            )}

            <CreateGalleryModal 
                isOpen={isCreateModalOpen} 
                onClose={() => setIsCreateModalOpen(false)} 
                onCreate={handleCreateGallery} 
            />

            {selectedGallery && (
                <GalleryDetailModal 
                    gallery={selectedGallery}
                    onClose={() => setSelectedGallery(null)}
                    onUpload={handleUploadImage}
                    onDeleteImage={handleDeleteImage}
                    onReorderImages={handleReorderImages}
                />
            )}
        </section>
    );
};

import { Gallery, GalleryImage } from '../types';

const STORAGE_KEY = 'tag_galleries';

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const DEFAULT_GALLERIES: Gallery[] = [
    {
        id: 'gallery_weekly_showcase',
        name: 'WEEKLY SHOWCASE',
        page: 'moes',
        description: 'Highlights from our weekly DJ live streams and showcase events.',
        images: [],
        createdAt: new Date().toISOString()
    },
    {
        id: 'gallery_under_la',
        name: 'UNDER LA',
        page: 'moes',
        description: 'Capturing the energy of our Monday Night Fundraiser community events.',
        images: [],
        createdAt: new Date().toISOString()
    },
    {
        id: 'gallery_studio_sessions',
        name: 'STUDIO SESSIONS',
        page: 'moes',
        description: 'Raw, unfiltered moments from recording and production blocks.',
        images: [],
        createdAt: new Date().toISOString()
    }
];

export const getGalleries = async (): Promise<Gallery[]> => {
    await delay(300); // Simulate network latency
    try {
        const data = localStorage.getItem(STORAGE_KEY);
        let galleries: Gallery[] = data ? JSON.parse(data) : [];

        // Ensure default galleries exist by merging them if missing
        let hasChanges = false;
        DEFAULT_GALLERIES.forEach(defaultGallery => {
            if (!galleries.find(g => g.id === defaultGallery.id)) {
                galleries.push(defaultGallery);
                hasChanges = true;
            }
        });

        // If storage was empty or defaults were added, save back to localStorage
        if (hasChanges || !data) {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(galleries));
        }

        return galleries;
    } catch (e) {
        console.error("Failed to load galleries", e);
        // Fallback to defaults on error
        return DEFAULT_GALLERIES;
    }
};

export const createGallery = async (name: string, page: Gallery['page'], description?: string): Promise<Gallery> => {
    await delay(300);
    const galleries = await getGalleries();
    const newGallery: Gallery = {
        id: Date.now().toString(),
        name,
        page,
        description,
        images: [],
        createdAt: new Date().toISOString()
    };
    galleries.push(newGallery);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(galleries));
    return newGallery;
};

export const deleteGallery = async (id: string): Promise<void> => {
    await delay(300);
    let galleries = await getGalleries();
    galleries = galleries.filter(g => g.id !== id);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(galleries));
};

export const uploadImageToGallery = async (galleryId: string, file: File): Promise<GalleryImage> => {
    // Basic base64 conversion - in a real backend this would upload to S3/Cloudinary/GCS
    const toBase64 = (file: File) => new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
    });

    const url = await toBase64(file);
    const newImage: GalleryImage = {
        id: Date.now().toString(),
        url,
        title: file.name,
        uploadedAt: new Date().toISOString()
    };

    // Simulate upload delay
    await delay(500);

    const galleries = await getGalleries();
    const galleryIndex = galleries.findIndex(g => g.id === galleryId);

    if (galleryIndex === -1) throw new Error("Gallery not found");

    galleries[galleryIndex].images.push(newImage);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(galleries));

    return newImage;
};

export const updateGalleryImages = async (galleryId: string, newImages: GalleryImage[]): Promise<void> => {
    await delay(100);
    const galleries = await getGalleries();
    const galleryIndex = galleries.findIndex(g => g.id === galleryId);

    if (galleryIndex === -1) throw new Error("Gallery not found");

    galleries[galleryIndex].images = newImages;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(galleries));
};

export const deleteImageFromGallery = async (galleryId: string, imageId: string): Promise<void> => {
    await delay(300);
    const galleries = await getGalleries();
    const galleryIndex = galleries.findIndex(g => g.id === galleryId);

    if (galleryIndex === -1) throw new Error("Gallery not found");

    galleries[galleryIndex].images = galleries[galleryIndex].images.filter(img => img.id !== imageId);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(galleries));
};

