                        <button type="submit" disabled={isSubmitting} className="px-6 py-2 bg-cyan-500 text-black font-bold rounded-full hover:bg-cyan-400 disabled:opacity-50">
                            {isSubmitting ? 'Creating...' : 'Create Gallery'}
