const StudioAudioPlayer: React.FC<{ playlist: typeof defaultFeaturedSessions }> = ({ playlist }) => {
    const [currentIndex, setCurrentIndex] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [progress, setProgress] = useState(0);
    const [duration, setDuration] = useState(0);
    const [volume, setVolume] = useState(0.8);
    const audioRef = useRef<HTMLAudioElement>(null);
    const [isImageLoaded, setIsImageLoaded] = useState(false);

    const currentTrack = playlist[currentIndex];

    useEffect(() => {
        setIsImageLoaded(false);
    }, [currentIndex]);

    const togglePlay = () => {
        if (!audioRef.current) return;
        if (isPlaying) audioRef.current.pause();
        else audioRef.current.play();
        setIsPlaying(!isPlaying);
    };

    const handleTimeUpdate = () => {
        if (!audioRef.current) return;
        const current = audioRef.current.currentTime;
        const total = audioRef.current.duration;
        setProgress((current / total) * 100);
    };

    const handleLoadedMetadata = () => {
        if (!audioRef.current) return;
        setDuration(audioRef.current.duration);
    };

    const handleProgressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!audioRef.current) return;
        const newTime = (parseFloat(e.target.value) / 100) * duration;
        audioRef.current.currentTime = newTime;
        setProgress(parseFloat(e.target.value));
    };

    const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const newVolume = parseFloat(e.target.value);
        setVolume(newVolume);
        if (audioRef.current) audioRef.current.volume = newVolume;
    };

    const nextTrack = () => {
        const next = (currentIndex + 1) % playlist.length;
        setCurrentIndex(next);
        setIsPlaying(true);
    };

    const prevTrack = () => {
        const prev = (currentIndex - 1 + playlist.length) % playlist.length;
        setCurrentIndex(prev);
        setIsPlaying(true);
    };

    const selectTrack = (index: number) => {
        setCurrentIndex(index);
        setIsPlaying(true);
    };

    // Auto-play when track changes if it was already playing
    useEffect(() => {
        if (isPlaying && audioRef.current) {
            audioRef.current.play().catch(() => setIsPlaying(false));
        }
    }, [currentIndex, isPlaying]);

    if (!currentTrack) return <div className="p-12 text-center text-gray-500 italic">No audio sessions available.</div>;

    return (
        <div className="bg-[#111] rounded-2xl border border-gray-800 shadow-2xl overflow-hidden flex flex-col lg:flex-row max-w-7xl mx-auto">
            {/* Left Section: Visuals & Main Controls */}
            <div className="flex-grow p-8 flex flex-col items-center justify-center border-b lg:border-b-0 lg:border-r border-gray-800 bg-gradient-to-br from-black to-gray-900">
                <div className="relative w-full max-w-sm aspect-square mb-8 group">
                    <div className="absolute inset-0 bg-fuchsia-500/10 rounded-xl blur-2xl animate-pulse group-hover:bg-fuchsia-500/20 transition-all"></div>
                    <div className="relative w-full h-full rounded-xl overflow-hidden border border-gray-700 bg-gray-900">
                        {!isImageLoaded && <div className="absolute inset-0 animate-shimmer z-10"></div>}
                        <img 
                            src={currentTrack.imageUrl} 
                            alt={currentTrack.title} 
                            onLoad={() => setIsImageLoaded(true)}
                            className={`w-full h-full object-cover transition-all duration-1000 ${isImageLoaded ? 'opacity-100 scale-100' : 'opacity-0 scale-105'}`}
                        />
                    </div>
                </div>

                <div className="text-center mb-8">
                    <p className="text-fuchsia-400 text-xs font-bold uppercase tracking-[0.2em] mb-2">Currently Tracking</p>
                    <h3 className="text-3xl font-bold text-white mb-1 uppercase tracking-wider">{currentTrack.title}</h3>
                    <p className="text-gray-400 text-lg">{currentTrack.artist}</p>
                </div>

                <div className="w-full max-w-md space-y-6">
                    {/* Progress Bar */}
                    <div className="space-y-2">
                        <input 
                            type="range" 
                            min="0" 
                            max="100" 
                            value={progress || 0} 
                            onChange={handleProgressChange}
                            className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-fuchsia-500"
                        />
                        <div className="flex justify-between text-[10px] text-gray-500 font-mono uppercase tracking-widest">
                            <span>{Math.floor(audioRef.current?.currentTime || 0).toString().padStart(2, '0')}:{Math.floor((audioRef.current?.currentTime || 0) % 60).toString().padStart(2, '0')}</span>
                            <span>{Math.floor(duration || 0).toString().padStart(2, '0')}:{Math.floor((duration || 0) % 60).toString().padStart(2, '0')}</span>
                        </div>
                    </div>

                    {/* Main Transport */}
                    <div className="flex items-center justify-center gap-8">
                        <button onClick={prevTrack} className="text-gray-400 hover:text-white transition-colors p-2" aria-label="Previous Track"><SkipBackIcon className="w-8 h-8" /></button>
                        <button 
                            onClick={togglePlay} 
                            className="w-16 h-16 rounded-full bg-fuchsia-600 text-white flex items-center justify-center hover:scale-110 hover:bg-fuchsia-500 transition-all shadow-[0_0_20px_rgba(217,70,239,0.3)]"
                            aria-label={isPlaying ? "Pause" : "Play"}
                        >
                            {isPlaying ? <PauseIcon className="w-8 h-8" /> : <PlayIcon className="w-8 h-8 ml-1" />}
                        </button>
                        <button onClick={nextTrack} className="text-gray-400 hover:text-white transition-colors p-2" aria-label="Next Track"><SkipForwardIcon className="w-8 h-8" /></button>
                    </div>

                    {/* Volume Control */}
                    <div className="flex items-center gap-4 px-8">
                        <VolumeIcon className="w-4 h-4 text-gray-500" />
                        <input 
                            type="range" 
                            min="0" 
                            max="1" 
                            step="0.01" 
                            value={volume} 
                            onChange={handleVolumeChange}
                            className="w-full h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-gray-500"
                        />
                    </div>
                </div>

                <audio 
                    ref={audioRef} 
                    src={currentTrack.audioUrl} 
                    onTimeUpdate={handleTimeUpdate}
                    onLoadedMetadata={handleLoadedMetadata}
                    onEnded={nextTrack}
                />
            </div>

            {/* Right Section: Playlist */}
            <div className="lg:w-96 flex flex-col bg-black/40 h-[400px] lg:h-auto">
                <header className="p-6 border-b border-gray-800 flex items-center justify-between">
                    <h4 className="text-sm font-bold text-white uppercase tracking-widest">Playlist</h4>
                    <span className="text-[10px] text-gray-500 font-mono uppercase tracking-widest">{playlist.length} Tracks</span>
                </header>
                <div className="flex-grow overflow-y-auto custom-scrollbar">
                    {playlist.map((track, index) => (
                        <button 
                            key={track.id}
                            onClick={() => selectTrack(index)}
                            className={`w-full flex items-center gap-4 p-4 text-left border-b border-gray-800/50 hover:bg-white/5 transition-colors group ${currentIndex === index ? 'bg-fuchsia-500/10' : ''}`}
                        >
                            <div className="relative w-12 h-12 flex-shrink-0 rounded overflow-hidden border border-gray-700">
                                <img src={track.imageUrl} alt="" className="w-full h-full object-cover" loading="lazy" />
                                {currentIndex === index && isPlaying && (
                                    <div className="absolute inset-0 bg-fuchsia-500/40 flex items-center justify-center">
                                        <div className="flex gap-0.5 items-end h-4">
                                            <div className="w-1 bg-white animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                                            <div className="w-1 bg-white animate-bounce" style={{ animationDelay: '0.3s' }}></div>
                                            <div className="w-1 bg-white animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                            <div className="min-w-0 flex-grow">
                                <h5 className={`text-sm font-bold truncate transition-colors ${currentIndex === index ? 'text-fuchsia-400' : 'text-gray-200'}`}>
                                    {track.title}
                                </h5>
                                <p className="text-xs text-gray-500 truncate">{track.artist}</p>
                            </div>
                            {currentIndex === index && <div className="w-1.5 h-1.5 rounded-full bg-fuchsia-500 shadow-[0_0_5px_#ff00ff]"></div>}
                        </button>
                    ))}
                </div>
            </div>
        </div>
    );
};

