const EditSessionModal: React.FC<{ session: FeaturedSession; onClose: () => void; onSave: (updatedSession: FeaturedSession) => void; }> = ({ session, onClose, onSave }) => {
  const [formData, setFormData] = useState(session);
  const [audioFile, setAudioFile] = useState<File | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files?.[0]) setAudioFile(e.target.files[0]); };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (audioFile) {
      const reader = new FileReader();
      reader.onload = () => onSave({ ...formData, audioUrl: reader.result as string });
      reader.readAsDataURL(audioFile);
    } else {
      onSave(formData);
    }
  };

  return (
    <Modal isOpen={true} onClose={onClose} ariaLabelledBy="edit-modal-title">
      <div className="bg-gray-900 rounded-lg shadow-2xl w-full border border-fuchsia-500/30 p-8">
        <h3 id="edit-modal-title" className="text-2xl font-bold text-fuchsia-400 mb-6 text-center uppercase tracking-widest">Edit Track Info</h3>
        <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <Input label="Artist / Performer" name="artist" value={formData.artist} onChange={handleChange} required />
                <Input label="Track Title" name="title" value={formData.title} onChange={handleChange} required />
            </div>
            <Textarea label="Liner Notes / Description" name="description" value={formData.description} onChange={handleChange} required />
            <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">Replace Audio Source</label>
                <input type="file" onChange={handleFileChange} accept="audio/*" className="w-full text-sm text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:bg-fuchsia-500/20 file:text-fuchsia-300" />
            </div>
            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={onClose} className="px-6 py-2 font-bold text-gray-300 bg-gray-700/50 rounded-full hover:bg-gray-700">Cancel</button>
                <button type="submit" className="px-6 py-2 font-bold text-black bg-fuchsia-500 rounded-full hover:scale-105">Save Changes</button>
            </div>
        </form>
      </div>
    </Modal>
  );
};

