interface FeaturedSessionsManagerProps {
  sessions: FeaturedSession[];
  setSessions: (sessions: FeaturedSession[]) => void;
  addToast: (message: string) => void;
}

export const FeaturedSessionsManager: React.FC<FeaturedSessionsManagerProps> = ({ sessions, setSessions, addToast }) => {
  const [newSession, setNewSession] = useState({ artist: '', title: '', description: '', imageUrl: '' });
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [editingSession, setEditingSession] = useState<FeaturedSession | null>(null);
  const [isImagePickerOpen, setIsImagePickerOpen] = useState(false);
  const [sessionToUpdateImage, setSessionToUpdateImage] = useState<FeaturedSession['id'] | 'new' | null>(null);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
  const [draggingIndex, setDraggingIndex] = useState<number | null>(null);

  const headingRef = useRef<HTMLHeadingElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleNewSessionChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setNewSession(prev => ({ ...prev, [e.target.name]: e.target.value }));
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files?.[0]) setAudioFile(e.target.files[0]); };

  const handleAddNewSession = (e: React.FormEvent) => {
    e.preventDefault();
    if (!audioFile) { alert('Audio file required.'); return; }
    if (!newSession.imageUrl) { alert('Track art required.'); return; }

    const reader = new FileReader();
    reader.onload = () => {
      const newSessionData: FeaturedSession = {
        ...newSession,
        id: Date.now(),
        audioUrl: reader.result as string,
      };
      setSessions([...sessions, newSessionData]);
      addToast('Track added to playlist.');
      setNewSession({ artist: '', title: '', description: '', imageUrl: '' });
      setAudioFile(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsDataURL(audioFile);
  };

  const handleDeleteSession = (id: number) => {
    if (window.confirm('Remove from playlist?')) {
      const deletedSession = sessions.find(s => s.id === id);
      setSessions(sessions.filter(s => s.id !== id));
      addToast(`Track removed.`);
      headingRef.current?.focus();
    }
  };

  const handleSaveEditedSession = (updatedSession: FeaturedSession) => {
    setSessions(sessions.map(s => s.id === updatedSession.id ? updatedSession : s));
    addToast(`Track updated.`);
    setEditingSession(null);
  };

  const handleDragStart = (e: React.DragEvent<HTMLLIElement>, index: number) => {
    dragItem.current = index;
    setDraggingIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnter = (e: React.DragEvent<HTMLLIElement>, index: number) => {
    e.preventDefault();
    dragOverItem.current = index;
    setDragOverIndex(index);
  };

  const handleDragOver = (e: React.DragEvent<HTMLLIElement>) => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; };

  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null && dragItem.current !== dragOverItem.current) {
        const newSessions = [...sessions];
        const draggedItemContent = newSessions.splice(dragItem.current, 1)[0];
        newSessions.splice(dragOverItem.current, 0, draggedItemContent);
        setSessions(newSessions);
        addToast('Playlist reordered.');
    }
    dragItem.current = null;
    dragOverItem.current = null;
    setDragOverIndex(null);
    setDraggingIndex(null);
  };

  const handleImageSelect = (dataUrl: string) => {
    if (sessionToUpdateImage === 'new') {
        setNewSession(prev => ({ ...prev, imageUrl: dataUrl }));
    } else if (sessionToUpdateImage) {
        setSessions(sessions.map(s => s.id === sessionToUpdateImage ? { ...s, imageUrl: dataUrl } : s));
        addToast("Track art updated.");
    }
    setIsImagePickerOpen(false);
  };

  const isAddSessionDisabled = sessions.length >= MAX_SESSIONS;

  return (
    <section>
      <h2 ref={headingRef} tabIndex={-1} className="text-3xl font-bold uppercase tracking-widest text-white mb-6 outline-none">Playlist Curator ({sessions.length}/{MAX_SESSIONS})</h2>

      <div className={`bg-gray-800/50 border border-gray-700 rounded-lg p-6 mb-8 ${isAddSessionDisabled ? 'opacity-50' : ''}`}>
        <h3 className="text-xl font-bold text-fuchsia-400 mb-4 uppercase tracking-widest">Add New Track</h3>
        <fieldset disabled={isAddSessionDisabled}>
          <form onSubmit={handleAddNewSession} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Input label="Artist" name="artist" value={newSession.artist} onChange={handleNewSessionChange} required /><Input label="Track Title" name="title" value={newSession.title} onChange={handleNewSessionChange} required /></div>
              <Textarea label="Liner Notes" name="description" value={newSession.description} onChange={handleNewSessionChange} required />
              <div className="flex items-start gap-4">
                <div className="flex-shrink-0">
                    <label className="block text-sm font-medium text-gray-300 mb-2">Track Art</label>
                    <div className="w-24 h-24 bg-gray-900 rounded-md flex items-center justify-center border border-gray-700 overflow-hidden">
                        {newSession.imageUrl ? <img src={newSession.imageUrl} alt="" className="w-full h-full object-cover" /> : <UploadIcon className="w-8 h-8 text-gray-700" />}
                    </div>
                </div>
                <div className="flex-grow pt-8">
                    <button type="button" onClick={() => { setSessionToUpdateImage('new'); setIsImagePickerOpen(true); }} className="px-4 py-2 text-sm font-bold text-cyan-400 bg-cyan-950/30 border border-cyan-800 rounded-full hover:bg-cyan-900/50">
                        {newSession.imageUrl ? 'Change Artwork' : 'Select Artwork'}
                    </button>
                </div>
              </div>
              <div className="space-y-1">
                <label className="block text-sm font-medium text-gray-400">Audio Source (Max {MAX_SIZE_MB}MB)</label>
                <input ref={fileInputRef} type="file" onChange={handleFileChange} accept="audio/*" required className="w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:bg-fuchsia-500/20 file:text-fuchsia-300" />
              </div>
              <div className="text-right"><button type="submit" className="px-10 py-3 font-bold text-black bg-fuchsia-500 rounded-full hover:scale-105 shadow-[0_0_15px_#ff00ff]">Add to Playlist</button></div>
          </form>
        </fieldset>
      </div>

      <div className="space-y-2">
        <div className="px-4 py-2 text-[10px] text-gray-500 font-mono uppercase tracking-[0.2em] flex justify-between">
            <span>Drag to Reorder</span>
            <span>Playlist Sequence</span>
        </div>
        {sessions.length > 0 ? (
            <ul className="space-y-2">
            {sessions.map((session, index) => (
                <li 
                key={session.id} 
                draggable 
                onDragStart={(e) => handleDragStart(e, index)}
                onDragEnter={(e) => handleDragEnter(e, index)}
                onDragEnd={handleDragEnd}
                onDragOver={handleDragOver}
                className={`bg-gray-800/50 border rounded-xl p-3 flex items-center gap-4 transition-all ${
                    dragOverIndex === index ? 'border-fuchsia-400 bg-gray-800 scale-[1.02]' : 'border-gray-800 hover:border-fuchsia-500/30'
                } ${draggingIndex === index ? 'opacity-40' : 'opacity-100'}`}
                >
                <div className="p-2 text-gray-600 hover:text-white cursor-grab"><DragHandleIcon className="w-5 h-5" /></div>
                <div className="relative flex-shrink-0 group">
                    <img src={session.imageUrl} alt="" className="w-12 h-12 rounded object-cover border border-gray-700" />
                    <button onClick={() => { setSessionToUpdateImage(session.id); setIsImagePickerOpen(true); }} className="absolute inset-0 bg-black/70 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity rounded">
                        <span className="text-white text-[10px] font-bold">Swap</span>
                    </button>
                </div>
                <div className="flex-grow min-w-0">
                    <p className="font-bold text-white truncate text-sm">{session.title}</p>
                    <p className="text-xs text-gray-500 truncate">{session.artist}</p>
                </div>
                <div className="flex-shrink-0 flex items-center gap-1">
                    <button onClick={() => setEditingSession(session)} className="p-2 text-gray-500 hover:text-cyan-400"><EditIcon className="w-4 h-4" /></button>
                    <button onClick={() => handleDeleteSession(session.id)} className="p-2 text-gray-500 hover:text-red-500"><CloseIcon className="w-4 h-4" /></button>
                </div>
                </li>
            ))}
            </ul>
        ) : <p className="text-center text-gray-600 italic py-8 border border-dashed border-gray-800 rounded-xl">Playlist is empty.</p>}
      </div>

      {editingSession && <EditSessionModal session={editingSession} onClose={() => setEditingSession(null)} onSave={handleSaveEditedSession} />}
      {isImagePickerOpen && <ImagePickerModal isOpen={isImagePickerOpen} onClose={() => setIsImagePickerOpen(false)} onImageSelect={handleImageSelect} addToast={addToast} />}
    </section>
  );
};

