        </div>

        <div className="animate-fade-in max-w-6xl mx-auto">
          {activeTab === 'submissions' && (
            <div role="tabpanel" className="max-w-5xl mx-auto">
              <DataTable
                  title="Studio Bookings"
                  items={bookings}
                  setItems={setBookings}
