    return (
        <button 
            onClick={() => onSelect(index)}
            className={`w-full flex items-center gap-4 p-4 text-left border-b border-gray-800/50 hover:bg-white/5 transition-colors group ${isActive ? 'bg-fuchsia-500/10' : ''}`}
