  useEffect(() => {
    const logoTimer = setTimeout(() => setLogoVisible(true), 500);
    return () => clearTimeout(logoTimer);
  }, []);

  useEffect(() => {
    const handleMouseMove = (event: MouseEvent) => {
        if (requestRef.current) return;
        const { clientX, clientY } = event;
        requestRef.current = requestAnimationFrame(() => {
            setMousePos({ x: clientX, y: clientY });
            requestRef.current = undefined;
        });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const backgroundStyle = {
    '--mouseX': `${mousePos.x}px`,
    '--mouseY': `${mousePos.y}px`,
    '--gradient-color': 'rgba(255, 0, 255, 0.15)',
    '--gradient-size': '40vw',
  } as React.CSSProperties;

  return (
    <div
      className="relative w-full bg-black overflow-x-hidden landing-page-container"
      style={backgroundStyle}
    >
      {/* Fixed Navigation/Logo Area */}
      <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-50 transition-all duration-1000 ease-out ${logoVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
        <img src={logoUrl} alt="Studio Logo" className="w-40 h-auto filter drop-shadow-[0_0_10px_rgba(255,0,255,0.5)]" loading="eager" />
      </div>

      {/* Hero Section (Parallax Layered) */}
      <section className="relative h-screen w-full flex items-center justify-center overflow-hidden">
        {/* Background Layer (Moves Slowest) */}
        <ParallaxLayer speed={0.4}>
            <div className="absolute inset-0">
                <video
                    className="w-full h-full object-cover opacity-60 scale-110"
                    autoPlay
                    loop
                    muted
                    playsInline
                    poster={MOES_IMAGE_URL}
                >
                    <source src={BACKGROUND_VIDEO_URL} type="video/mp4" />
                </video>
                <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-black/40 to-black"></div>
            </div>
        </ParallaxLayer>

        {/* Mid-ground Decorative Layer (Moves Medium) */}
        <ParallaxLayer speed={0.2} className="z-10">
            <div className="absolute inset-0 flex items-center justify-center opacity-10" style={blueprintStyleFuchsia}></div>
            <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-fuchsia-500/10 rounded-full blur-[120px] animate-pulse"></div>
