const HeroCollageItem: React.FC<{ session: Session; index: number; className?: string }> = ({ session, index, className = '' }) => {
    const [currentImageIdx, setCurrentImageIdx] = useState(0);
    const [loadedImages, setLoadedImages] = useState<Set<number>>(new Set());

    const handleImageLoad = (idx: number) => {
        setLoadedImages(prev => new Set(prev).add(idx));
    };

    const isFirstImageLoaded = loadedImages.has(0);

    useEffect(() => {
        if (!isFirstImageLoaded) return;
        const intervalDuration = 4000 + (index * 1500); 
        const interval = setInterval(() => {
            setCurrentImageIdx(prev => (prev + 1) % session.images.length);
        }, intervalDuration);
        return () => clearInterval(interval);
    }, [session.images.length, index, isFirstImageLoaded]);

    return (
        <article className={`relative rounded-3xl overflow-hidden group shadow-2xl border border-white/5 bg-gray-900 transition-all duration-1000 ${className}`}>
            {!isFirstImageLoaded && (
                <div className="absolute inset-0 animate-shimmer z-40" aria-hidden="true" />
            )}

            {/* Blurred Background Glow */}
            {session.images.map((img, idx) => (
                <div
                    key={`bg-${idx}`}
                    className={`absolute inset-0 w-full h-full bg-cover bg-center blur-[60px] opacity-20 transition-opacity duration-1000 ${idx === currentImageIdx ? 'opacity-30' : 'opacity-0'}`}
                    style={{ backgroundImage: `url(${img})` }}
                />
            ))}

            {/* Main Images */}
            {session.images.map((img, idx) => (
                <img
                    key={idx}
                    src={img}
                    alt={`${session.artist} Studio View ${idx + 1}`}
                    onLoad={() => handleImageLoad(idx)}
                    decoding="async"
                    className={`absolute inset-0 w-full h-full object-cover transition-all duration-1000 ease-in-out filter blur-md grayscale-[0.5] group-hover:blur-0 group-hover:grayscale-0 group-hover:scale-105 ${
                        idx === currentImageIdx && loadedImages.has(idx)
                        ? 'opacity-100 z-10' 
                        : 'opacity-0 z-0'
                    }`}
                    loading={index === 0 && idx === 0 ? "eager" : "lazy"}
                />
            ))}

            {/* Artistic Overlays */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/10 to-transparent z-20 group-hover:bg-black/20 transition-all duration-700"></div>
            <div className="absolute inset-0 border-[20px] border-white/[0.02] pointer-events-none z-30 group-hover:border-transparent transition-all duration-700"></div>

            <div className="absolute bottom-0 left-0 w-full p-8 z-30 transform transition-all duration-500 group-hover:-translate-y-2">
                <div className="border-l-[3px] border-fuchsia-500/50 group-hover:border-fuchsia-500 pl-5 transition-colors">
                    <h3 className="text-xl md:text-3xl font-bold text-white uppercase tracking-widest mb-2 leading-tight" style={{ textShadow: '0 4px 12px rgba(0,0,0,0.8)' }}>
                        {session.artist}
                    </h3>
                    <p className="text-gray-400 text-xs md:text-sm line-clamp-2 opacity-0 group-hover:opacity-100 transition-all duration-700 delay-200 font-medium">
                        {session.description}
                    </p>
                </div>
            </div>
        </article>
    );
};

