import React, { useMemo } from 'react';
import type { VisualAidData } from '../types';

const freqToX = (f: number) => {
  const min = Math.log10(20);
  const max = Math.log10(20000);
  const val = Math.log10(f);
  return ((val - min) / (max - min)) * 100;
};

const gainToY = (g: number) => {
  // Assume gain range is -18 to +18 for EQ, or 0 to 1 for generic response
  // Map to 0-100 range for SVG viewbox
  const min = -18;
  const max = 18;
  const range = max - min;
  const normalized = (g - min) / range;
  return 100 - (normalized * 100); // SVG Y is top-down
};

export const VisualAid: React.FC<{ data: VisualAidData }> = ({ data }) => {
  const { points, title, labels } = data;

  const pathData = useMemo(() => {
    if (!points || points.length < 2) return '';
    const sortedPoints = [...points].sort((a, b) => a.f - b.f);
    return sortedPoints.reduce((acc, pt, i) => {
      const x = freqToX(pt.f);
      const y = gainToY(pt.g);
      return acc + (i === 0 ? `M ${x} ${y}` : ` L ${x} ${y}`);
    }, '');
  }, [points]);

  const gridLines = [100, 1000, 10000];

  return (
    <div className="mt-4 p-4 bg-black/40 border border-fuchsia-500/30 rounded-xl overflow-hidden animate-fade-in backdrop-blur-sm">
      <div className="flex justify-between items-center mb-3">
        <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-fuchsia-400">{title}</h4>
        <span className="text-[8px] text-gray-500 font-mono">ANALYSIS_MODE: ON</span>
      </div>

      <div className="relative aspect-[2/1] w-full bg-gray-900/50 rounded border border-white/5">
        <svg viewBox="0 0 100 100" className="w-full h-full" preserveAspectRatio="none">
          {/* Grid lines */}
          {gridLines.map(f => (
            <line 
              key={f} 
              x1={freqToX(f)} y1="0" x2={freqToX(f)} y2="100" 
              stroke="rgba(255,255,255,0.05)" strokeWidth="0.5" 
            />
          ))}
          <line x1="0" y1="50" x2="100" y2="50" stroke="rgba(255,255,255,0.1)" strokeWidth="0.5" strokeDasharray="2,2" />

          {/* Data Path */}
          <path 
            d={pathData} 
            fill="none" 
            stroke="url(#neonGradient)" 
            strokeWidth="2" 
            strokeLinecap="round" 
            strokeLinejoin="round"
            className="drop-shadow-[0_0_5px_rgba(217,70,239,0.5)]"
          />

          <defs>
            <linearGradient id="neonGradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#00ffff" />
              <stop offset="100%" stopColor="#ff00ff" />
            </linearGradient>
          </defs>
        </svg>

        {/* Labels */}
        <div className="absolute inset-0 pointer-events-none text-[8px] font-bold text-gray-600 uppercase flex justify-between px-1 items-end pb-1">
          <span>20Hz</span>
          <span className="ml-[-10%]">1kHz</span>
          <span>20kHz</span>
        </div>
      </div>

      {labels && labels.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-2">
          {labels.map((l, i) => (
            <div key={i} className="flex items-center gap-1.5">
              <div className="w-1.5 h-1.5 rounded-full bg-cyan-400"></div>
              <span className="text-[9px] text-gray-400 font-bold uppercase">{l.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

