**Tone Example:**
"I love that vision. To get that 'crystalline' vocal, I'd put you on the Sony C800G. Check out the top-end lift on this response graph—it captures the air in a way no other mic can. Ready to track?"
`;

// --- Tool Definitions ---

const renderVisualAidFunctionDeclaration: FunctionDeclaration = {
  name: 'renderVisualAid',
  description: 'Renders a visual aid (frequency response or EQ curve) to help the user visualize sonic changes.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      type: {
        type: Type.STRING,
        description: 'The type of visualization, e.g., "frequency_response", "eq_curve".',
      },
      title: {
        type: Type.STRING,
        description: 'A short descriptive title for the graph.',
      },
      points: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            f: { type: Type.NUMBER, description: 'Frequency in Hz (20 to 20000).' },
            g: { type: Type.NUMBER, description: 'Gain in dB (-18 to 18) or 0 to 1 for response.' },
          },
          required: ['f', 'g'],
        },
        description: 'A series of points defining the curve.',
      },
      labels: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            f: { type: Type.NUMBER, description: 'Frequency of the label.' },
            label: { type: Type.STRING, description: 'The text label for that frequency region.' },
          },
          required: ['f', 'label'],
        },
        description: 'Optional labels to highlight specific regions (e.g., "Air", "Presence", "Body").',
      }
    },
    required: ['type', 'title', 'points'],
  },
};

const getStudioPackagesFunctionDeclaration: FunctionDeclaration = {
  name: 'getStudioPackages',
  description: 'Retrieves a list of available studio packages, optionally filtered by category.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      category: {
        type: Type.STRING,
        description: 'The category to filter by, e.g., "Recording & Tracking", "Production & Mixing".',
      },
    },
    required: [],
  },
};

const createStudioBookingFunctionDeclaration: FunctionDeclaration = {
  name: 'createStudioBooking',
  description: 'Creates a new booking request for a studio session.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      packageName: { type: Type.STRING, description: 'The exact name of the package to book.' },
      date: { type: Type.STRING, description: 'The desired date for the booking in YYYY-MM-DD format.' },
      time: { type: Type.STRING, description: 'The desired time for the booking in 24-hour HH:MM format.' },
      name: { type: Type.STRING, description: 'The full name of the person booking.' },
