const CollageItem: React.FC<{ session: Session; index: number }> = ({ session, index }) => {
    const [currentImageIdx, setCurrentImageIdx] = useState(0);
    const [loadedImages, setLoadedImages] = useState<Set<number>>(new Set());

    const handleImageLoad = (idx: number) => {
        setLoadedImages(prev => new Set(prev).add(idx));
    };

    useEffect(() => {
        if (!loadedImages.has(0)) return;
        const interval = setInterval(() => {
            setCurrentImageIdx(prev => (prev + 1) % session.images.length);
        }, 5000 + (index * 1200));
        return () => clearInterval(interval);
    }, [session.images.length, index, loadedImages]);

    return (
        <article 
            className={`transition-all duration-700 hover:z-[60] ${session.positionClass} ${session.widthClass} ${session.zIndex}`}
            style={{ 
                transform: `rotate(${session.rotation}deg)`,
                perspective: '1000px'
            }}
        >
            <div className="group relative overflow-hidden rounded-[2.5rem] shadow-[0_30px_100px_rgba(0,0,0,0.6)] border border-white/10 bg-black backdrop-blur-3xl transition-all duration-700 group-hover:rotate-0 group-hover:scale-[1.03] group-hover:shadow-fuchsia-500/30">

                {/* Torn Edges Effect */}
                <div className="absolute inset-0 z-30 pointer-events-none border-[15px] border-black/20 mix-blend-overlay"></div>

                {/* Tape strips */}
                {index === 0 && <TapeOverlay position="top" />}
                {index === 1 && <TapeOverlay position="right" />}
                {index === 2 && <TapeOverlay position="left" />}

                {/* Main Visuals with Blur Clarification */}
                <div className="aspect-[14/9] relative overflow-hidden">
                    {session.images.map((img, idx) => (
                        <img
                            key={idx}
                            src={img}
                            alt=""
                            onLoad={() => handleImageLoad(idx)}
                            className={`absolute inset-0 w-full h-full object-cover transition-all duration-1000 filter blur-xl grayscale group-hover:blur-0 group-hover:grayscale-0 scale-110 group-hover:scale-100 ${
                                idx === currentImageIdx ? 'opacity-100' : 'opacity-0'
                            }`}
                        />
                    ))}
                    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent z-10 opacity-80 group-hover:opacity-60"></div>
                </div>

                {/* Content Overlay */}
                <div className="absolute bottom-0 left-0 w-full p-8 lg:p-10 z-20">
                    <h3 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tighter mb-2 group-hover:text-fuchsia-400 transition-colors">
                        {session.artist}
                    </h3>
                    <p className="text-gray-400 text-xs font-bold leading-relaxed opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-y-4 group-hover:translate-y-0">
                        {session.description}
                    </p>
                </div>
            </div>
        </article>
    );
};

