              stroke="rgba(255,255,255,0.05)" strokeWidth="0.5" 
            />
          ))}
          <line x1="0" y1="50" x2="100" y2="50" stroke="rgba(255,255,255,0.1)" strokeWidth="0.5" strokeDasharray="2,2" />

          <path 
            d={pathData} 
            fill="none" 
            stroke="url(#neonGradient)" 
            strokeWidth="2" 
            strokeLinecap="round" 
            strokeLinejoin="round"
            className="drop-shadow-[0_0_5px_rgba(217,70,239,0.5)]"
          />

          <defs>
            <linearGradient id="neonGradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#00ffff" />
              <stop offset="100%" stopColor="#ff00ff" />
            </linearGradient>
          </defs>
        </svg>

        <div className="absolute inset-0 pointer-events-none text-[8px] font-bold text-gray-600 uppercase flex justify-between px-1 items-end pb-1">
          <span>20Hz</span>
          <span className="ml-[-10%]">1kHz</span>
          <span>20kHz</span>
        </div>
      </div>

      {labels && labels.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-2">
          {labels.map((l, i) => (
            <div key={i} className="flex items-center gap-1.5">
              <div className="w-1.5 h-1.5 rounded-full bg-cyan-400"></div>
              <span className="text-[9px] text-gray-400 font-bold uppercase">{l.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

