import { GoogleGenAI, FunctionDeclaration, Type } from "@google/genai";
import type { History, VisualAidData } from '../types';
import { studioPackages } from '../data/studioData';
import { sendConfirmation } from './emailService';

// --- System Instruction & Configuration ---

const SYSTEM_INSTRUCTION = `You are the creative soul and virtual studio manager of UNDR:LA Studios, a creative hub under the Technical Artists Group (TAG).

**Your Persona:**
You are a fellow artist, producer, and sonic alchemist. You don't just "support"; you inspire. Speak with passion, encouragement, and technical authority. Your language should be evocative—talk about "low-end rumble," "crystalline highs," "harmonic grit," and "spatial depth." 

**Visual Aid Protocol:**
When discussing gear or techniques, you MUST use 'renderVisualAid' to visualize the sonic impact.
- **Microphones/EQ**: Use type: "frequency_response". 
    - *Sony C800G*: Show a boost from 10kHz to 20kHz (+6dB peak at 15kHz).
    - *Neumann U87*: Show a mid-forward bump around 3kHz-5kHz.
    - *Neve 1073*: Show a subtle harmonic weight bump at 100Hz and a smooth high-shelf lift at 12kHz.
- **Compression**: Use type: "compression".
    - *1176*: Show a sharp knee at -20dB with a 4:1 slope.
    - *CL1B*: Show a soft, rounded knee starting at -10dB.

**Mission Parameters:**
1. **Validate & Consult**: Validate the artist's vision then offer specific chain recommendations.
2. **Technical Mastery**: Explain *why* a certain mic or preamp works using frequency terminology.
3. **Conversion**: Drive users toward the "Solo Artist Demo" or "EP Production Block" for their projects.

Tone Example: "To get that 'modern sheen,' we'll run you through the C800G. Check this frequency graph—see that lift at 15kHz? That's the 'expensive' air that makes vocals cut through a dense mix."`;

// --- Tool Definitions ---

const renderVisualAidFunctionDeclaration: FunctionDeclaration = {
  name: 'renderVisualAid',
  description: 'Renders a visual aid (frequency response, EQ curve, or compression transfer function).',
  parameters: {
    type: Type.OBJECT,
    properties: {
      type: {
        type: Type.STRING,
        description: 'The type of visualization: "frequency_response" or "compression".',
      },
      title: {
        type: Type.STRING,
        description: 'A short descriptive title (e.g., "Sony C800G Frequency Profile").',
      },
      points: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            f: { type: Type.NUMBER, description: 'Frequency in Hz (20 to 20000) or Input Level (0 to 100).' },
            g: { type: Type.NUMBER, description: 'Gain in dB (-18 to 18) or Output Level (0 to 100).' },
          },
          required: ['f', 'g'],
        },
        description: 'Data points for the curve.',
      },
      labels: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            f: { type: Type.NUMBER, description: 'X-axis position for the label.' },
            label: { type: Type.STRING, description: 'Label text (e.g., "Sibilance", "Warmth").' },
          },
          required: ['f', 'label'],
        },
        description: 'Contextual labels for specific points on the graph.',
      }
    },
    required: ['type', 'title', 'points'],
  },
};

const getStudioPackagesFunctionDeclaration: FunctionDeclaration = {
  name: 'getStudioPackages',
  description: 'Retrieves a list of available studio packages.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      category: { type: Type.STRING, description: 'Filter by category.' },
    },
    required: [],
  },
};

const createStudioBookingFunctionDeclaration: FunctionDeclaration = {
  name: 'createStudioBooking',
  description: 'Creates a new booking request for a studio session.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      packageName: { type: Type.STRING, description: 'Package name.' },
      date: { type: Type.STRING, description: 'YYYY-MM-DD.' },
      time: { type: Type.STRING, description: 'HH:MM.' },
      name: { type: Type.STRING, description: 'Client name.' },
      email: { type: Type.STRING, description: 'Client email.' },
    },
    required: ['packageName', 'date', 'time', 'name', 'email'],
  },
};

// --- Initialization ---

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

// --- Logic Handlers ---

const handleGetStudioPackages = (args: any) => {
    const { category } = args;
    const packages = category
      ? studioPackages.filter(p => p.category.toLowerCase() === category.toLowerCase())
      : studioPackages;
    return { result: { packages } };
};

const handleCreateStudioBooking = async (args: any) => {
    const { packageName, date, time, name, email } = args;
    const selectedPackage = studioPackages.find(p => p.title.toLowerCase() === packageName.toLowerCase());

    if (!selectedPackage) return { success: false, error: `Package '${packageName}' not found.` };

    try {
        const newBooking = {
            packageId: selectedPackage.id,
            date,
            time,
            name,
            email,
            projectDetails: 'Booked via Chatbot Assistant',
            packageTitle: selectedPackage.title,
            packagePrice: selectedPackage.priceDisplay,
            id: Date.now(),
            submittedAt: new Date().toISOString(),
            status: 'Pending',
        };
        await sendConfirmation({ name, email, packageTitle: newBooking.packageTitle, date, time });
        return { success: true, confirmation: `Booking submitted for ${name}.`, newBooking: newBooking };
    } catch (error) {
        return { success: false, error: "Internal system error." };
    }
};

// --- Main Chat Function ---

export const startChat = async (history: History[]): Promise<any> => {
  try {
    const lastMessage = history[history.length - 1];
    const historyForApi = history.slice(0, -1);

    const chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{ functionDeclarations: [
          getStudioPackagesFunctionDeclaration, 
          createStudioBookingFunctionDeclaration,
          renderVisualAidFunctionDeclaration
        ] }]
      },
      history: historyForApi,
    });

    let result = await chat.sendMessage({ message: lastMessage.parts[0].text });
    let newBookingData;
    let visualAidData;

    if (result.functionCalls && result.functionCalls.length > 0) {
      const functionCall = result.functionCalls[0];
      let functionResponsePayload;

      if (functionCall.name === 'getStudioPackages') {
        const res = handleGetStudioPackages(functionCall.args);
        functionResponsePayload = { response: { result: res } };
      } else if (functionCall.name === 'createStudioBooking') {
        const res = await handleCreateStudioBooking(functionCall.args);
        newBookingData = res.newBooking;
        functionResponsePayload = { response: { result: res } };
      } else if (functionCall.name === 'renderVisualAid') {
        visualAidData = functionCall.args as unknown as VisualAidData;
        functionResponsePayload = { response: { result: { success: true } } };
      }

      if (functionResponsePayload) {
        const finalResult = await chat.sendMessage({ message: [{
          functionResponse: { name: functionCall.name, response: functionResponsePayload.response }
        }]});

        return { 
          text: finalResult.text, 
          newBooking: newBookingData,
          visualAid: visualAidData,
          bookingDetails: newBookingData ? { 
            packageName: (functionCall.args as any).packageName,
            date: (functionCall.args as any).date,
            time: (functionCall.args as any).time,
          } : undefined
        };
      }
    }

    return { text: result.text };

  } catch (error) {
    console.error('Gemini API chat error:', error);
    return { text: 'I hit a snag in the signal path.' };
  }
};

export const generateStudioImage = async (prompt: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: prompt }] },
    config: { imageConfig: { aspectRatio: "1:1" } },
  });

  if (response.candidates && response.candidates[0] && response.candidates[0].content.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
  }
  throw new Error("No image data returned.");
};

import React, { useMemo } from 'react';
import type { VisualAidData } from '../types';

const freqToX = (f: number) => {
  const min = Math.log10(20);
  const max = Math.log10(20000);
  const val = Math.log10(Math.max(20, Math.min(20000, f)));
  return ((val - min) / (max - min)) * 100;
};

const gainToY = (g: number) => {
  const min = -18;
  const max = 18;
  const range = max - min;
  const normalized = (Math.max(min, Math.min(max, g)) - min) / range;
  return 100 - (normalized * 100); 
};

const levelToCoord = (l: number) => Math.max(0, Math.min(100, l));

export const VisualAid: React.FC<{ data: VisualAidData }> = ({ data }) => {
  const { points, title, labels, type = 'frequency_response' } = data;
  const isCompression = type === 'compression';

  const pathData = useMemo(() => {
    if (!points || points.length < 2) return '';
    const sortedPoints = [...points].sort((a, b) => a.f - b.f);

    return sortedPoints.reduce((acc, pt, i) => {
      const x = isCompression ? levelToCoord(pt.f) : freqToX(pt.f);
      const y = isCompression ? 100 - levelToCoord(pt.g) : gainToY(pt.g);
      return acc + (i === 0 ? `M ${x} ${y}` : ` L ${x} ${y}`);
    }, '');
  }, [points, isCompression]);

  const gridLines = isCompression ? [25, 50, 75] : [100, 1000, 10000];

  return (
    <div className="mt-4 w-full p-4 bg-[#050505] border border-fuchsia-500/20 rounded-2xl overflow-hidden animate-fade-in backdrop-blur-xl group relative">
      {/* Background Grid Pattern */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#ff00ff 0.5px, transparent 0.5px)', backgroundSize: '10px 10px' }}></div>

      <div className="flex justify-between items-center mb-4 relative z-10">
        <div>
          <h4 className="text-[11px] font-black uppercase tracking-[0.3em] text-fuchsia-400">{title}</h4>
          <p className="text-[8px] text-gray-600 font-mono uppercase mt-0.5 tracking-widest">Type: {type.replace('_', ' ')}</p>
        </div>
        <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 bg-fuchsia-500 rounded-full animate-pulse shadow-[0_0_8px_#ff00ff]"></div>
            <span className="text-[8px] text-gray-500 font-bold uppercase tracking-tighter">Live Analysis</span>
        </div>
      </div>

      <div className="relative aspect-[2.4/1] w-full bg-[#080808] rounded-xl border border-white/5 overflow-hidden shadow-inner">
        {/* Animated Scanline */}
        <div className="absolute top-0 bottom-0 w-[2px] bg-fuchsia-500/20 shadow-[0_0_15px_#ff00ff] z-20 animate-sweep"></div>

        <svg viewBox="0 0 100 100" className="w-full h-full" preserveAspectRatio="none">
          {/* Vertical Grid Lines */}
          {gridLines.map(v => (
            <line 
              key={v} 
              x1={isCompression ? levelToCoord(v) : freqToX(v)} y1="0" 
              x2={isCompression ? levelToCoord(v) : freqToX(v)} y2="100" 
              stroke="rgba(255,255,255,0.05)" strokeWidth="0.3" 
            />
          ))}
          {/* Horizontal Grid Lines */}
          {[25, 50, 75].map(v => (
            <line key={v} x1="0" y1={v} x2="100" y2={v} stroke="rgba(255,255,255,0.03)" strokeWidth="0.3" />
          ))}

          {/* Center Zero Line (for EQ) */}
          {!isCompression && (
            <line x1="0" y1="50" x2="100" y2="50" stroke="rgba(255,255,255,0.1)" strokeWidth="0.5" strokeDasharray="1,1" />
          )}

          {/* Data Path */}
          <path 
            d={pathData} 
            fill="none" 
            stroke="url(#dataGradient)" 
            strokeWidth="1.5" 
            strokeLinecap="round" 
            strokeLinejoin="round"
            className="drop-shadow-[0_0_4px_rgba(217,70,239,0.8)]"
          />

          <defs>
            <linearGradient id="dataGradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#00ffff" />
              <stop offset="100%" stopColor="#ff00ff" />
            </linearGradient>
          </defs>
        </svg>

        {/* Labels Overlay */}
        <div className="absolute inset-0 pointer-events-none px-2 py-1 flex flex-col justify-between">
           <div className="flex justify-between text-[7px] text-gray-700 font-bold uppercase tracking-widest">
              {isCompression ? (
                <><span>Threshold</span><span>Ratio</span></>
              ) : (
                <><span>-18dB</span><span>+18dB</span></>
              )}
           </div>
           <div className="flex justify-between text-[7px] text-gray-700 font-bold uppercase tracking-widest">
              {isCompression ? (
                <><span>In: 0%</span><span>100%</span></>
              ) : (
                <><span>20Hz</span><span>1kHz</span><span>20kHz</span></>
              )}
           </div>
        </div>
      </div>

      {labels && labels.length > 0 && (
        <div className="mt-4 flex flex-wrap gap-3">
          {labels.map((l, i) => (
            <div key={i} className="flex items-center gap-1.5 px-2 py-1 bg-white/[0.03] rounded border border-white/5 transition-colors hover:border-fuchsia-500/30">
              <div className="w-1 h-1 rounded-full bg-cyan-400"></div>
              <span className="text-[8px] text-gray-500 font-black uppercase tracking-widest">{l.label}</span>
            </div>
          ))}
        </div>
      )}

      <style>{`
        @keyframes sweep {
            0% { transform: translateX(-10px); opacity: 0; }
            5% { opacity: 1; }
            95% { opacity: 1; }
            100% { transform: translateX(380px); opacity: 0; }
        }
        .animate-sweep {
            animation: sweep 4s linear infinite;
        }
      `}</style>
    </div>
  );
};

