import React, { useState, Suspense, lazy } from 'react';
import SEO from './components/SEO';

const LandingPage = lazy(() => import('./components/LandingPage'));
const StudioView = lazy(() => import('./components/StudioView'));
const Chatbot = lazy(() => import('./components/Chatbot'));

const Loader = () => (
  <div className="flex items-center justify-center h-screen w-screen bg-black">
    <div className="w-12 h-12 border-2 border-fuchsia-500/20 border-t-fuchsia-500 rounded-full animate-spin" />
  </div>
);

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'studio'>('landing');

  return (
    <div className="min-h-screen bg-black text-gray-200 selection:bg-fuchsia-500 selection:text-white">
      <SEO title={view === 'landing' ? 'Welcome' : 'The Studio'} />
      <Suspense fallback={<Loader />}>
        {view === 'landing' ? (
          <LandingPage onNavigate={() => setView('studio')} />
        ) : (
          <StudioView onBack={() => setView('landing')} />
        )}
        <Chatbot />
      </Suspense>
    </div>
  );
