import { GoogleGenAI, Type } from "@google/genai";
import type { History, VisualAidData } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

const SYSTEM = `You are the Lead Engineer for UNDR:LA Studios.
You specialize in 'Sonic Diagnostics'. When users describe a room, a gear chain, or a mix issue, provide a technical readout.
Use elitist but helpful audio engineering terms (LUFS, phase coherence, comb filtering).
Always offer 'renderVisualAid' when discussing EQ or Dynamics.
Use gemini-3-flash-preview for high speed. Be concise.`;

export const startChat = async (history: History[]): Promise<any> => {
  const lastMsg = history[history.length - 1].parts[0].text;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: history,
    config: {
      systemInstruction: SYSTEM,
      tools: [{
        functionDeclarations: [{
          name: 'renderVisualAid',
          description: 'Renders technical audio curves.',
          parameters: {
            type: Type.OBJECT,
            properties: {
              type: { type: Type.STRING, enum: ['frequency_response', 'compression'] },
              title: { type: Type.STRING },
              points: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: { f: { type: Type.NUMBER }, g: { type: Type.NUMBER } },
                  required: ['f', 'g']
                }
              }
            },
            required: ['type', 'title', 'points']
          }
        }]
      }]
    }
  });

  const calls = response.candidates?.[0]?.content?.parts?.filter(p => p.functionCall);
  if (calls && calls.length > 0) {
    const call = calls[0].functionCall!;
    if (call.name === 'renderVisualAid') {
      return { text: response.text, visualAid: call.args as unknown as VisualAidData };
    }
  }

  return { text: response.text };
};

import { GoogleGenAI, Type } from "@google/genai";
