};

/**
 * Generates a creative studio-themed image based on a prompt.
 * @param prompt - The text description for the image generation.
 * @returns A base64 data URL of the generated image.
 */
export const generateStudioImage = async (prompt: string): Promise<string> => {
  // Use gemini-2.5-flash-image for general image generation tasks.
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          text: prompt,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: "1:1"
      }
    },
  });

  // Iterate through response parts to find the generated image (inlineData).
  const candidate = response.candidates?.[0];
  if (candidate?.content?.parts) {
    for (const part of candidate.content.parts) {
      if (part.inlineData) {
        const base64EncodeString: string = part.inlineData.data;
        return `data:image/png;base64,${base64EncodeString}`;
      }
    }
  }

  throw new Error("Failed to generate image: No image part found in the response.");
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { startChat } from '../services/geminiService';
